def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    units = [(10**9, 'bi'), (10**6, 'mi'), (10**3, 'mil')]

    for factor, label in units:
        v = n / factor
        # Round half up to 1 decimal place
        rounded_v = int(v * 10 + 0.5) / 10.0

        # Check if this is the correct unit (must be >= 1 and not round to 1000)
        # or if it's the largest available unit (bi)
        if rounded_v >= 1:
            if rounded_v < 1000 or label == 'bi':
                # Format the number: 1 decimal place, comma as decimal separator
                # If the decimal is .0, drop it.
                if rounded_v == int(rounded_v):
                    return f"{int(rounded_v)} {label}"
                else:
                    # Format like "1,5"
                    return f"{rounded_v:.1f}".replace('.', ',')
            else:
                # If it rounded to 1000, it should have been handled by the next unit
                continue

    return ""
