import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Identify all unique nodes in the graph
    all_nodes = set(deps.keys())
    for dependencies in deps.values():
        all_nodes.update(dependencies)

    # Initialize adjacency list and in-degree count
    # adj maps a dependency to the items that depend on it
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for item, dependencies in deps.items():
        in_degree[item] = len(dependencies)
        for d in dependencies:
            adj[d].append(item)

    # Priority queue for items with no remaining dependencies
    # Using a heap ensures we always pick the alphabetically smallest first
    ready = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        u = heapq.heappop(ready)
        order.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(ready, v)

    # If the order doesn't contain all nodes, there is a cycle
    if len(order) != len(all_nodes):
        raise ValueError("Cycle detected")

    return order
