def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    pieces = []
    for word in words:
        if len(word) <= width:
            pieces.append(word)
        else:
            # Split word into pieces of length 'width'
            for i in range(0, len(word), width):
                pieces.append(word[i : i + width])

    lines = []
    current_line = []
    current_len = 0

    for piece in pieces:
        # If piece is the first word in a line
        if not current_line:
            current_line.append(piece)
            current_len = len(piece)
        else:
            # Check if piece fits on current line with a preceding space
            if current_len + 1 + len(piece) <= width:
                current_line.append(piece)
                current_len += 1 + len(piece)
            else:
                # Line is full, start a new one
                lines.append(" ".join(current_line))
                current_line = [piece]
                current_len = len(piece)

    if current_line:
        lines.append(" ".join(current_line))

    return lines
