def compare_versions(a: str, b: str) -> int:
    def parse_version(v_str: str):
        # Build metadata (after +) is ignored
        core = v_str.split('+')[0]
        # Split main version and pre-release
        parts = core.split('-', 1)
        main_parts = parts[0].split('.')
        main_version = [int(x) for x in main_parts]

        pre_release = []
        if len(parts) > 1:
            pre_parts = parts[1].split('.')
            for p in pre_parts:
                if p.isdigit():
                    pre_release.append(int(p))
                else:
                    pre_release.append(p)
        return main_version, pre_release

    nums_a, pre_a = parse_version(a)
    nums_b, pre_b = parse_version(b)

    # Compare main version numbers
    for x, y in zip(nums_a, nums_b):
        if x < y:
            return -1
        if x > y:
            return 1

    # If main version numbers are equal, handle pre-release logic
    # Rule: A pre-release version has lower precedence than a normal version.
    if not pre_a and pre_b:
        return 1
    if pre_a and not pre_b:
        return -1
    if not pre_a and not pre_b:
        return 0

    # Both have pre-releases, compare dot by dot
    for x, y in zip(pre_a, pre_b):
        # Numeric identifiers are compared as numbers
        if isinstance(x, int) and isinstance(y, int):
            if x < y:
                return -1
            if x > y:
                return 1
        # Numeric identifiers are lower than alphanumeric identifiers
        elif isinstance(x, int) and not isinstance(y, int):
            return -1
        elif not isinstance(x, int) and isinstance(y, int):
            return 1
        # Alphanumeric identifiers compared lexicographically
        else:
            if x < y:
                return -1
            if x > y:
                return 1

    # When all earlier identifiers are equal, the shorter list is lower
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1

    return 0
