    # Priority queue for items with no remaining dependencies
    # Using a heap ensures we take the alphabetically smallest item first
    queue = [item for item in all_items if in_degree[item] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

