def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_line_len = 0

    for word in words:
        if len(word) <= width:
            # Treat as a normal word that is not split
            if not current_line:
                current_line.append(word)
                current_line_len = len(word)
            else:
                # Check if it fits with a space
                if current_line_len + 1 + len(word) <= width:
                    current_line.append(word)
                    current_line_len += 1 + len(word)
                else:
                    lines.append(" ".join(current_line))
                    current_line = [word]
                    current_line_len = len(word)
        else:
            # Word is longer than width and must be split into pieces
            chunks = [word[i:i + width] for i in range(0, len(word), width)]

            for i, chunk in enumerate(chunks):
                if i == 0:
                    # The first chunk of a long word behaves like a new word
                    if not current_line:
                        current_line.append(chunk)
                        current_line_len = len(chunk)
                    else:
                        if current_line_len + 1 + len(chunk) <= width:
                            current_line.append(chunk)
                            current_line_len += 1 + len(chunk)
                        else:
                            lines.append(" ".join(current_line))
                            current_line = [chunk]
                            current_line_len = len(chunk)
                else:
                    # Subsequent chunks of the same word have no space before them
                    if current_line_len + len(chunk) <= width:
                        current_line.append(chunk)
                        current_line_len += len(chunk)
                    else:
                        # Must start a new line, and since it's a continuation,
                        # the chunk is appended directly to the start of the new line
                        lines.append(" ".join(current_line))
                        current_line = [chunk]
                        current_line_len = len(chunk)

    if current_line:
        lines.append(" ".join(current_line))

    return lines
