from datetime import datetime

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    best_records = {}
    order = []

    for record in records:
        val = record[key]
        # Handle Z suffix for older Python versions and parse ISO 8601
        ts_str = record['updated_at'].replace('Z', '+00:00')
        current_dt = datetime.fromisoformat(ts_str)

        if val not in best_records:
            order.append(val)
            best_records[val] = (current_dt, record)
        else:
            best_dt, _ = best_records[val]
            # If current is later or equal (tie), update the record
            if current_dt >= best_dt:
                best_records[val] = (current_dt, record)

    return [best_records[val][1] for val in order]
