from datetime import date, timedelta

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    def is_business_day(dt: date) -> bool:
        # Weekday 0-4 are Monday-Friday
        return dt.weekday() < 5 and dt not in holidays

    if n == 0:
        if is_business_day(d):
            return d
        curr = d + timedelta(days=1)
        while not is_business_day(curr):
            curr += timedelta(days=1)
        return curr

    curr = d
    step = 1 if n > 0 else -1
    while n != 0:
        curr += timedelta(days=step)
        if is_business_day(curr):
            n -= step

    return curr
