def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Remove build metadata
        v = v.split('+')[0]
        # Separate release and pre-release
        parts = v.split('-', 1)
        release_part = parts[0]
        pre_release_part = parts[1] if len(parts) > 1 else None

        # Release version components as integers
        release_nums = [int(x) for x in release_part.split('.')]
        return release_nums, pre_release_part

    release_a, pre_a_str = parse_version(a)
    release_b, pre_b_str = parse_version(b)

    # Compare major, minor, patch (release parts)
    for x, y in zip(release_a, release_b):
        if x < y:
            return -1
        if x > y:
            return 1

    # If release parts are equal, check pre-release existence
    # Rule: pre-release is lower than release
    if pre_a_str is None and pre_b_str is None:
        return 0
    if pre_a_str is None:
        return 1
    if pre_b_str is None:
        return -1

    # Compare pre-release identifiers dot by dot
    pre_a = pre_a_str.split('.')
    pre_b = pre_b_str.split('.')

    for a_id, b_id in zip(pre_a, pre_b):
        a_is_num = a_id.isdigit()
        b_is_num = b_id.isdigit()

        if a_is_num and b_is_num:
            val_a = int(a_id)
            val_b = int(b_id)
            if val_a < val_b:
                return -1
            if val_a > val_b:
                return 1
        elif a_is_num:
            # Numeric identifiers are lower than alphanumeric ones
            return -1
        elif b_is_num:
            # Numeric identifiers are lower than alphanumeric ones
            return 1
        else:
            # Both alphanumeric: lexicographical comparison
            if a_id < b_id:
                return -1
            if a_id > b_id:
                return 1

    # If all previous identifiers are equal, shorter list is lower
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1

    return 0
