import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Identify all nodes involved in the graph
    all_nodes = set()
    for item, dependencies in deps.items():
        all_nodes.add(item)
        for d in dependencies:
            all_nodes.add(d)

    # Build adjacency list (dependency -> items depending on it)
    # and calculate in-degrees (number of dependencies for each item)
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for item, dependencies in deps.items():
        in_degree[item] = len(dependencies)
        for d in dependencies:
            adj[d].append(item)

    # Priority queue for Kahn's algorithm to maintain alphabetical order
    # Items with in_degree 0 are ready to be processed
    queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    order = []
    while queue:
        u = heapq.heappop(queue)
        order.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(order) != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return order
```

