def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    tokens = []
    for word in words:
        if len(word) <= width:
            tokens.append(word)
        else:
            for i in range(0, len(word), width):
                tokens.append(word[i : i + width])

    lines = []
    current_line = []
    current_length = 0

    for token in tokens:
        # If current_line is empty, just add the token
        if not current_line:
            current_line.append(token)
            current_length = len(token)
        else:
            # Check if adding a space + token fits
            if current_length + 1 + len(token) <= width:
                current_line.append(token)
                current_length += 1 + len(token)
            else:
                # Line is full, join and start new one
                lines.append(" ".join(current_line))
                current_line = [token]
                current_length = len(token)

    if current_line:
        lines.append(" ".join(current_line))

    return lines
