def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.split('\n')
    section_found = False
    key_found = False
    current_section = None

    # Track the search state
    # We only look for the key if we are currently inside the target section.
    # If we leave the target section without finding the key, we stop looking.
    in_target_section = False

    for i in range(len(lines)):
        line = lines[i]
        stripped = line.strip()

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            current_section = stripped[1:-1]
            if current_section == section:
                section_found = True
                in_target_section = True
            else:
                in_target_section = False
            continue

        # If we are inside the target section and haven't found the key yet
        if in_target_section and not key_found:
            if '=' in line:
                parts = line.split('=', 1)
                k = parts[0].strip()
                if k == key:
                    lines[i] = f"{key} = {value}"
                    key_found = True

    if not section_found:
        raise KeyError(f"Section [{section}] not found.")
    if not key_found:
        raise KeyError(f"Key '{key}' not found in section [{section}].")

    return '\n'.join(lines)
