import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        addr = ipaddress.ip_address(ip)

        # Handle IPv4-mapped IPv6 addresses: e.g., '::ffff:10.0.0.5'
        # The ipaddress module recognizes these as IPv6Address objects.
        # We check if the address is in the ::ffff:0:0/96 range.
        if isinstance(addr, ipaddress.IPv6Address):
            # ::ffff:0:0/96 is the standard prefix for IPv4-mapped IPv6
            # We can check this by looking at the packed bytes.
            # IPv4-mapped addresses have the prefix 0000:0000:0000:0000:0000:ffff:0000:0000
            if addr.packed[6:12] == b'\xff\xff\x00\x00\x00\x00':
                # Extract the last 4 bytes to get the IPv4 address
                addr = ipaddress.IPv4Address(addr.packed[12:])

        for net_str in networks:
            try:
                # strict=False allows networks with host bits set (e.g., '10.0.0.1/8')
                network = ipaddress.ip_network(net_str, strict=False)
                if addr in network:
                    return True
            except ValueError:
                raise ValueError(f"Invalid network: {net_str}")

        return False
    except ValueError:
        # If ip is invalid, ipaddress.ip_address raises ValueError
        return False
